[metadata] {"type": "create", "filePath": "/app/presentation.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cloudflare Radar 2024 Year in Review</title>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500&display=swap" rel="stylesheet">
    <style>
        /* === BASE RESET & VIEWPORT === */
        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        html, body {
            height: 100%;
            overflow-x: hidden;
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background: #0a0a0f;
            color: #ffffff;
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        /* === SLIDE SYSTEM === */
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            padding: clamp(1.5rem, 5vw, 4rem);
        }

        /* === CLOUDFLARE DARK THEME === */
        :root {
            --cf-orange: #f6821f;
            --cf-blue: #1e3a8a;
            --cf-dark: #0a0a0f;
            --cf-navy: #0f172a;
            --cf-slate: #1e293b;
            --cf-gray: #334155;
            --cf-light-gray: #94a3b8;
            --cf-white: #f8fafc;
            --cf-green: #22c55e;
            --cf-red: #ef4444;
            --cf-yellow: #eab308;

            --title-size: clamp(1.8rem, 5vw, 3.5rem);
            --h2-size: clamp(1.4rem, 3.5vw, 2.5rem);
            --h3-size: clamp(1.1rem, 2.5vw, 1.5rem);
            --body-size: clamp(0.85rem, 1.8vw, 1.2rem);
            --small-size: clamp(0.7rem, 1.2vw, 0.95rem);

            --slide-padding: clamp(1.5rem, 5vw, 4rem);
            --content-gap: clamp(0.75rem, 2vw, 2rem);
        }

        /* === SLIDE 1: TITLE === */
        .slide-title {
            background: linear-gradient(135deg, var(--cf-dark) 0%, var(--cf-navy) 50%, #1a2744 100%);
        }

        .slide-title::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background:
                radial-gradient(ellipse at 20% 80%, rgba(246, 130, 31, 0.15) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 20%, rgba(30, 58, 138, 0.2) 0%, transparent 50%);
            pointer-events: none;
        }

        .slide-title .slide-content {
            text-align: center;
            align-items: center;
            justify-content: center;
        }

        .slide-title h1 {
            font-size: var(--title-size);
            font-weight: 800;
            letter-spacing: -0.03em;
            margin-bottom: var(--content-gap);
            background: linear-gradient(135deg, var(--cf-white) 0%, #cbd5e1 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            position: relative;
            z-index: 1;
        }

        .slide-title .subtitle {
            font-size: var(--h3-size);
            color: var(--cf-light-gray);
            font-weight: 500;
            letter-spacing: 0.02em;
            position: relative;
            z-index: 1;
        }

        .slide-title .year-badge {
            display: inline-block;
            background: var(--cf-orange);
            color: var(--cf-dark);
            font-weight: 700;
            font-size: var(--small-size);
            padding: 0.4em 1em;
            border-radius: 4px;
            margin-top: var(--content-gap);
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        /* === SLIDE 2: TRAFFIC GROWTH === */
        .slide-growth {
            background: linear-gradient(180deg, var(--cf-navy) 0%, var(--cf-dark) 100%);
        }

        .slide-growth .slide-content {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            align-items: center;
        }

        .stat-card {
            background: linear-gradient(135deg, rgba(30, 58, 138, 0.3) 0%, rgba(15, 23, 42, 0.8) 100%);
            border: 1px solid rgba(246, 130, 31, 0.3);
            border-radius: 12px;
            padding: clamp(1.5rem, 3vw, 2.5rem);
        }

        .stat-card h3 {
            font-size: var(--small-size);
            color: var(--cf-orange);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-bottom: 0.5em;
        }

        .stat-card .big-number {
            font-size: clamp(3rem, 8vw, 6rem);
            font-weight: 800;
            color: var(--cf-white);
            line-height: 1;
        }

        .stat-card .big-number span {
            color: var(--cf-orange);
        }

        .stat-card p {
            font-size: var(--body-size);
            color: var(--cf-light-gray);
            margin-top: 0.5em;
        }

        .slide h2 {
            font-size: var(--h2-size);
            font-weight: 700;
            color: var(--cf-white);
            margin-bottom: var(--content-gap);
            grid-column: 1 / -1;
        }

        .slide h2 .highlight {
            color: var(--cf-orange);
        }

        .slide img {
            max-width: 100%;
            max-height: 45vh;
            border-radius: 8px;
            object-fit: contain;
        }

        /* === SLIDE 3: TOP 10 SERVICES === */
        .slide-services {
            background: var(--cf-dark);
        }

        .slide-services .slide-content {
            display: grid;
            grid-template-columns: 1.2fr 1fr;
            gap: var(--content-gap);
            align-items: start;
        }

        .slide-services h2 {
            font-size: var(--h2-size);
            font-weight: 700;
            color: var(--cf-white);
            margin-bottom: var(--content-gap);
        }

        .slide-services h2 .highlight {
            color: var(--cf-orange);
        }

        .ranking-table {
            width: 100%;
            border-collapse: collapse;
        }

        .ranking-table th,
        .ranking-table td {
            padding: clamp(0.4rem, 1vw, 0.75rem) clamp(0.6rem, 1.5vw, 1rem);
            text-align: left;
            font-size: var(--small-size);
        }

        .ranking-table th {
            color: var(--cf-orange);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            font-weight: 600;
            border-bottom: 2px solid var(--cf-gray);
        }

        .ranking-table td {
            color: var(--cf-white);
            border-bottom: 1px solid rgba(148, 163, 184, 0.2);
        }

        .ranking-table tr:nth-child(1) td { color: #ffd700; }
        .ranking-table tr:nth-child(2) td { color: #c0c0c0; }
        .ranking-table tr:nth-child(3) td { color: #cd7f32; }

        .ranking-table .rank {
            font-weight: 700;
            color: var(--cf-orange);
            width: 3em;
        }

        .slide-services img {
            max-height: 50vh;
            border-radius: 8px;
        }

        .ai-callout {
            background: linear-gradient(135deg, rgba(246, 130, 31, 0.2) 0%, rgba(30, 58, 138, 0.2) 100%);
            border-left: 4px solid var(--cf-orange);
            padding: clamp(0.75rem, 1.5vw, 1.25rem);
            margin-top: var(--content-gap);
            grid-column: 1 / -1;
            border-radius: 0 8px 8px 0;
        }

        .ai-callout p {
            font-size: var(--body-size);
            color: var(--cf-light-gray);
        }

        .ai-callout strong {
            color: var(--cf-orange);
        }

        /* === SLIDE 4: TECHNOLOGY ADOPTION === */
        .slide-tech {
            background: linear-gradient(135deg, var(--cf-navy) 0%, var(--cf-dark) 100%);
        }

        .slide-tech .slide-content {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            grid-template-rows: auto 1fr;
            gap: var(--content-gap);
        }

        .slide-tech h2 {
            font-size: var(--h2-size);
            font-weight: 700;
            color: var(--cf-white);
            grid-column: 1 / -1;
            margin-bottom: 0;
        }

        .slide-tech h2 .highlight {
            color: var(--cf-orange);
        }

        .metric-card {
            background: rgba(15, 23, 42, 0.8);
            border: 1px solid var(--cf-gray);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
            display: flex;
            flex-direction: column;
            justify-content: center;
        }

        .metric-card.highlight-card {
            border-color: var(--cf-orange);
            background: linear-gradient(135deg, rgba(246, 130, 31, 0.15) 0%, rgba(15, 23, 42, 0.9) 100%);
        }

        .metric-card .metric-label {
            font-size: var(--small-size);
            color: var(--cf-light-gray);
            text-transform: uppercase;
            letter-spacing: 0.08em;
            margin-bottom: 0.5em;
        }

        .metric-card .metric-value {
            font-size: clamp(2rem, 5vw, 3.5rem);
            font-weight: 800;
            color: var(--cf-white);
            line-height: 1.1;
        }

        .metric-card .metric-value span {
            color: var(--cf-orange);
        }

        .metric-card .metric-subtext {
            font-size: var(--small-size);
            color: var(--cf-light-gray);
            margin-top: 0.5em;
        }

        .metric-card .from-to {
            display: flex;
            align-items: center;
            gap: 0.5em;
            font-size: var(--body-size);
        }

        .metric-card .from-to .start {
            color: var(--cf-light-gray);
        }

        .metric-card .from-to .arrow {
            color: var(--cf-green);
        }

        .metric-card .from-to .end {
            color: var(--cf-orange);
            font-weight: 700;
        }

        .slide-tech img {
            max-height: 35vh;
            border-radius: 8px;
            align-self: center;
        }

        /* === SLIDE 5: DISRUPTIONS === */
        .slide-disruptions {
            background: var(--cf-dark);
        }

        .slide-disruptions .slide-content {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            align-items: start;
        }

        .slide-disruptions h2 {
            font-size: var(--h2-size);
            font-weight: 700;
            color: var(--cf-white);
            grid-column: 1 / -1;
        }

        .slide-disruptions h2 .highlight {
            color: var(--cf-red);
        }

        .disruption-chart {
            background: rgba(15, 23, 42, 0.8);
            border: 1px solid var(--cf-gray);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
        }

        .bar-chart {
            display: flex;
            flex-direction: column;
            gap: 0.6em;
        }

        .bar-row {
            display: flex;
            align-items: center;
            gap: 0.75em;
        }

        .bar-label {
            width: 9em;
            font-size: var(--small-size);
            color: var(--cf-light-gray);
            text-align: right;
            flex-shrink: 0;
        }

        .bar-container {
            flex: 1;
            height: 24px;
            background: var(--cf-slate);
            border-radius: 4px;
            overflow: hidden;
        }

        .bar-fill {
            height: 100%;
            border-radius: 4px;
            transition: width 1s ease-out;
        }

        .bar-fill.government { background: linear-gradient(90deg, var(--cf-red), #dc2626); }
        .bar-fill.cable { background: linear-gradient(90deg, #f59e0b, #d97706); }
        .bar-fill.unknown { background: linear-gradient(90deg, var(--cf-gray), #475569); }
        .bar-fill.power { background: linear-gradient(90deg, #8b5cf6, #7c3aed); }
        .bar-fill.other { background: linear-gradient(90deg, var(--cf-blue), #1e40af); }

        .bar-value {
            width: 2.5em;
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--cf-white);
            text-align: right;
        }

        .slide-disruptions img {
            max-height: 45vh;
            border-radius: 8px;
        }

