            color: var(--cf-red);
        }

        /* === SLIDE 6: SECURITY === */
        .slide-security {
            background: linear-gradient(180deg, var(--cf-navy) 0%, var(--cf-dark) 100%);
        }

        .slide-security .slide-content {
