            font-weight: 700;
            color: var(--cf-white);
            grid-column: 1 / -1;
        }

        .slide-security h2 .highlight {
            color: var(--cf-green);
        }

        .security-stat {
            background: rgba(15, 23, 42, 0.8);
            border: 1px solid var(--cf-gray);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
        }

