            font-size: var(--small-size);
            color: var(--cf-light-gray);
            text-transform: uppercase;
            letter-spacing: 0.08em;
            margin-bottom: 0.5em;
        }

        .security-stat .stat-number {
            font-size: clamp(2rem, 5vw, 3.5rem);
            font-weight: 800;
            color: var(--cf-white);
        }

        .security-stat .stat-number span {
            color: var(--cf-green);
        }

        .security-stat .stat-desc {
            font-size: var(--small-size);
            color: var(--cf-light-gray);
            margin-top: 0.5em;
        }

