            transform: translateY(-4px);
            border-color: var(--cf-orange);
        }

        .takeaway-card .number {
            width: 2.5em;
            height: 2.5em;
            background: var(--cf-orange);
            color: var(--cf-dark);
            font-size: var(--h3-size);
            font-weight: 800;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 0.75em;
        }

        .takeaway-card h4 {
            font-size: var(--body-size);
            color: var(--cf-white);
            font-weight: 600;
            margin-bottom: 0.5em;
            line-height: 1.3;
        }

        .takeaway-card p {
            font-size: var(--small-size);
            color: var(--cf-light-gray);
            line-height: 1.4;
        }

        /* === NAVIGATION === */
        .nav-dots {
            position: fixed;
            right: clamp(0.5rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 0.5rem;
            z-index: 100;
        }

        .nav-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background: var(--cf-gray);
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .nav-dot.active {
            background: var(--cf-orange);
            transform: scale(1.3);
        }

        /* === ANIMATIONS === */
        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(30px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes scaleIn {
            from {
