        .slide:nth-child(1) .slide-content > *:nth-child(1) { animation-delay: 0.1s; }
        .slide:nth-child(1) .slide-content > *:nth-child(2) { animation-delay: 0.2s; }
        .slide:nth-child(1) .slide-content > *:nth-child(3) { animation-delay: 0.3s; }

